solution.Solution.java:
public class Solution {
    static boolean isPrime(int n) {
        if (n < 2) return false;
        for (int d = 2; (long) d * d <= n; d++) {
            if (n % d == 0) return false;
        }
        return true;
    }

    static int gcd(int a, int b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            int r = a % b;
            a = b;
            b = r;
        }
        return a;
    }

    static int digitSum(long n) {
        n = Math.abs(n);
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }

    static double area(double radius) {
        return Math.PI * radius * radius;
    }

    static double area(double width, double height) {
        return width * height;
    }

    static String repeat(String s, int times, String separator) {
        String result = "";
        for (int i = 0; i < times; i++) {
            if (i > 0) result += separator;
            result += s;
        }
        return result;
    }
}

unitTests:
test("primes", () -> {
    checkEq(Solution.isPrime(2), true);
    checkEq(Solution.isPrime(97), true);
    checkEq(Solution.isPrime(1), false);
    checkEq(Solution.isPrime(-7), false);
    checkEq(Solution.isPrime(91), false);
    checkEq(Solution.isPrime(2147483647), true);
});

test("greatest common divisor", () -> {
    checkEq(Solution.gcd(84, 36), 12);
    checkEq(Solution.gcd(17, 5), 1);
    checkEq(Solution.gcd(-12, 18), 6);
    checkEq(Solution.gcd(0, 9), 9);
    checkEq(Solution.gcd(0, 0), 0);
});

test("digit sums", () -> {
    checkEq(Solution.digitSum(90210), 12);
    checkEq(Solution.digitSum(-555), 15);
    checkEq(Solution.digitSum(0), 0);
    checkEq(Solution.digitSum(9_999_999_999L), 90);
});

test("overloaded areas", () -> {
    checkNear(Solution.area(1), Math.PI);
    checkNear(Solution.area(2.0, 3.5), 7.0);
});

test("repeat", () -> {
    checkEq(Solution.repeat("ab", 3, "-"), "ab-ab-ab");
    checkEq(Solution.repeat("x", 1, ","), "x");
    checkEq(Solution.repeat("x", 0, ","), "");
});

